{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue party gathers at the edge of the ruined city.",
      "visual_description": "A rain-slick overlook above a shattered royal skyline, broken spires silhouetted against a green dusk. Mara unrolls a map on a stone block while the tin fox sniffs the wind.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "Mara lights the oracle lamp and asks for the safest path.",
      "visual_description": "Close-up of an oil lamp with a single glowing eye flickering inside the flame, casting amber light across Mara's ink-stained fingers and brass compass.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The glass diver arrives by stepping out of a cracked window.",
      "visual_description": "A figure in a clear diving helmet emerges from a tall broken window, coat shimmering with reflected city lights, water beading off the brim though no water is visible.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "They approach the looming castle gates.",
      "visual_description": "Massive iron gates hang half-off their hinges under a torn royal banner. The tin fox trots ahead, its key-wind tail clicking, blue glass eyes glowing faintly in the gloom.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "A leaning tower wrapped in violet mist looms over a courtyard. The lamp's eye narrows; purple sparks drift from the flame as Mara shields it with her coat.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "The party finds the sleeping tax collector slumped at his booth.",
      "visual_description": "A dusty toll booth at the inner gate. A round official snores on top of a ledger pillow, stamped papers fluttering from his sleeves with each breath.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Mara tries to question him about the captive's location.",
      "visual_description": "Mara leans in with her compass, tapping the ledger. The tax collector mumbles, drool smudging an old wax seal. The tin fox tilts its metal head, unimpressed.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "An armored patrol marches past on the boulevard below.",
      "visual_description": "From a high broken balcony, the group watches lantern light and helmet plumes pass between rubble piles. The glass diver presses flat against a tall mirror set into the wall.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The glass diver slips through a mirror to scout ahead.",
      "visual_description": "Mid-dive: the diver's coat ripples into the silver surface of a tall standing mirror, fingers reaching through as if into deep water. Mara watches from behind, lamp raised.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Tin fox sniffs out a hidden royal banner stairwell.",
      "visual_description": "Tattered banners of a fallen crown drape over a spiral stair. The tin fox's tail winds itself tighter; one paw lifts, pointing down into the dark.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "Rumors of a great winged beast echo from the cathedral square.",
      "visual_description": "Cracked stained glass throws colored light over an empty plaza. A long shadow sweeps across the cobbles. Mara grips her compass; the oracle lamp's eye widens.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The glass diver returns with the captive's exact location.",
      "visual_description": "The diver rises from a shallow rain puddle on the cathedral floor, helmet streaming light, sketching a quick floor plan in chalk across the broken tiles.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "They reach the magic door sealing the inner keep.",
      "visual_description": "A circular door inlaid with shifting silver runes pulses softly. The oracle lamp's flame leans toward one rune; Mara traces it with the tip of her compass.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The sleeping tax collector mutters the seal phrase in his dreams.",
      "visual_description": "Carried in a wheelbarrow, the official mumbles into his ledger pillow. A glowing word drifts from his lips toward the door. The tin fox stares, head cocked.",
      "characters": ["sleeping_tax_collector", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "The door opens and the glass diver dives through its surface.",
      "visual_description": "The runed door turns liquid like quicksilver. The diver plunges in head-first, coat flaring with reflected torchlight, leaving a single ripple behind.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "The patrol discovers them and the chase begins.",
      "visual_description": "Helmeted shapes pour through a far archway. Mara hoists the lamp, the tin fox sprints ahead with sparks flying from its paws, and the diver emerges from a window holding a small sealed casket.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the long stone bridge out of the city.",
      "visual_description": "A narrow bridge spans a fog-filled chasm. Cracked statues line each side. The party runs full-tilt; the tax collector bounces in the wheelbarrow, still asleep, papers streaming behind him.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far side, they look back at the ruined skyline.",
      "visual_description": "Dawn breaks pink over the broken city. Mara folds her map with a faint smile, the lamp's eye half-closed, the tin fox curled on the diver's boots, the tax collector still snoring against a milestone.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

